<?php
 require_once('utilsTrait.php'); trait med_cisz_allergyIntolerance { use med_cisz_utilsTrait; private function createAllergyIntolerance(): void { $patientId = $this->patientId ?? null; $visit = $this->visitPatient[array_key_first($this->visitPatient)]; if (!$this->normalizeStrictBool(self::getHtmDataValue($visit->htmData, ['ARG']))) { return; } $allergyJson = self::getHtmDataValue($visit->htmData, ['ARGTX1']); $allergy = safe_json_decode($allergyJson)->code; if (!$allergy) { return; } $allergyArrayId = array_map('intval', array_map('trim', explode(',', $allergy))); if (!$allergyArrayId) { return; } foreach ($allergyArrayId as $id) { $sql = <<<SQL
            SELECT
                MA.MedAllergyCode                                        "allergyId",
                MA.MedPatientCode                                        "patientId",
                MA.Type                                                  "typeAllergy",
                MA.DateDetection                                         "dateDetection",
                MA.DateLastReaction                                      "dateLastReaction",
                MA.DateDetectionText                                     "dateDetectionText",
                MA.MedDoctorCode                                         "doctorId",
                FN_cmFIO(MD.ManCode, 1)                                  "doctor",
                MA.CiszResourceValueCodeCauses                           "causesAllergyId",
                CRVC.Name                                                "causesAllergy",
                CRVC.Code                                                "causesAllergyCode",
                MA.Json                                                  "allergenAllergyJson",
                MA.AllergenSubstance                                     "substanceAllergy",
                MA.CiszResourceValueCodeClinicalStatus                   "clinicalStatusId",
                CRVS.Code                                                "clinicalStatusCode",
                CRVS.Name                                                "clinicalStatus",
                MA.CiszResourceValueCodeVerifyStatus                     "verificationAllergyStatusId",
                CRVV.Name                                                "verificationAllergyStatus",
                CRVV.Code                                                "verificationAllergyStatusCode",
                MA.Criticality                                           "criticalityAllergy",
                MA.Note                                                  "noteAllergy",
                -------------------------------------------------------------------------------------
                MAR.MedAllergyReactionCode                               "reactionId",
                MAR.OnDateTime                                           "reactionDate",
                MAR.AllergenSubstance                                    "allergenSubstanceReaction",
                MAR.MedDiagnosisCode                                     "diagnosisId",
                MDG.cipher1                                              "diagnosisCipher",
                MDG.Name                                                 "diagnosis",
                MAR.CiszResourceValueCodeRoute                           "roteId",
                CRVR.Name                                                "rote",
                CRVR.Code                                                "roteCode",
                MAR.Description                                          "reactionDescription",
                MAR.Note                                                 "reactionNote"
            FROM MedAllergy AS MA
                LEFT JOIN CiszResourceValue AS CRVC ON CRVC.CiszResourceValueCode = MA.CiszResourceValueCodeCauses
                LEFT JOIN CiszResourceValue AS CRVV ON CRVV.CiszResourceValueCode = MA.CiszResourceValueCodeVerifyStatus
                LEFT JOIN CiszResourceValue AS CRVS ON CRVS.CiszResourceValueCode = MA.CiszResourceValueCodeClinicalStatus
                LEFT JOIN MedDoctor AS MD ON MD.MedDoctorCode = MA.MedDoctorCode
                LEFT JOIN MedAllergyReaction AS MAR ON MAR.MedAllergyCode = MA.MedAllergyCode
                LEFT JOIN MedDiagnosis AS MDG ON MDG.MedDiagnosisCode = MAR.MedDiagnosisCode
                LEFT JOIN CiszResourceValue AS CRVR ON CRVR.CiszResourceValueCode = MAR.CiszResourceValueCodeRoute
                LEFT JOIN MedDayHopsitalPurpose AS MDHP ON MDHP.MedAllergyCode = MA.MedAllergyCode
            WHERE MA.MedAllergyCode = :id
            SQL;
$stmt = $this->db->prepare($sql); $stmt->execute([':id' => $id]); $allergies = $stmt->fetchAll(PDO::FETCH_OBJ); foreach ($allergies as $item) { if ($item->typeAllergy === 1) { $item->typeCode = 'allergy'; } elseif ($item->typeAllergy === 2) { $item->typeCode = 'intolerance'; } if ($item->criticalityAllergy === 1) { $item->criticalityCode = 'low'; } elseif ($item->criticalityAllergy === 2) { $item->criticalityCode = 'high'; } elseif ($item->criticalityAllergy === 3) { $item->criticalityCode = 'unable-to-assess'; } } $reactionIds = []; foreach ($allergies as $item) { if (!empty($item->reactionId)) { $reactionIds[] = $item->reactionId; } } $allergyIds = []; foreach ($allergies as $item) { if (!empty($item->allergyId) && !in_array($item->allergyId, $allergyIds)) { $allergyIds[] = $item->allergyId; } } $vitalSignsByReaction = $this->getVitalSignsForReactions($reactionIds); foreach ($allergies as &$item) { $reactionId = $item->reactionId; if (isset($vitalSignsByReaction[$reactionId])) { $item->vitalSigns = $vitalSignsByReaction[$reactionId]; } else { $item->vitalSigns = []; } } if (!empty($reactionIds)) { $placeholders = implode(',', array_fill(0, count($reactionIds), '?')); $sqlMeasures = 'SELECT
                    MARTS.MedAllergyReactionCode    "reactionId",
                    MARTS.CiszResourceValueCode     "measureId",
                    CRVRS.Name                      "measureName",
                    CRVRS.Code                      "measureCode"
                FROM MedAllergyReactionToStop AS MARTS
                LEFT JOIN CiszResourceValue AS CRVRS ON CRVRS.CiszResourceValueCode = MARTS.CiszResourceValueCode
                WHERE MARTS.MedAllergyReactionCode IN (' . $placeholders . ')'; $stmtMeasures = $this->db->prepare($sqlMeasures); $stmtMeasures->execute($reactionIds); $measures = $stmtMeasures->fetchAll(); $measuresByReaction = []; foreach ($measures as $measure) { $reactionId = $measure['reactionId']; if (!isset($measuresByReaction[$reactionId])) { $measuresByReaction[$reactionId] = [ 'ids' => [], 'names' => [], 'codde' => [] ]; } $measuresByReaction[$reactionId]['ids'][] = $measure['measureId']; $measuresByReaction[$reactionId]['names'][] = $measure['measureName']; $measuresByReaction[$reactionId]['code'][] = $measure['measureCode']; } foreach ($allergies as &$item) { $reactionId = $item->reactionId; if (isset($measuresByReaction[$reactionId])) { $item->measuresForReliefIds = $measuresByReaction[$reactionId]['ids']; $item->measuresForRelief = $measuresByReaction[$reactionId]['names']; $item->measuresForReliefCodes = $measuresByReaction[$reactionId]['code']; } else { $item->measuresForReliefIds = []; $item->measuresForRelief = []; } } } foreach ($allergies as $allergy) { $this->allergyIntolerance[] = $allergy; $allergy->allergenAllergy = $allergy->allergenAllergyJson ? json_decode($allergy->allergenAllergyJson)->allergyMedication : null; self::createDocumentReferences($allergy->allergyId, 120); $allergy->documentsByAllergy = $this->documentReference; $id = generateUUID(null, null, true); $allergyAnamnesis = (object) [ 'fullUrl' => 'AllergyIntolerance/' . $id, 'resource' => (object) [ 'resourceType' => 'AllergyIntolerance', 'id' => $id, 'meta' => (object) [ 'profile' => [med_cisz_constant::$structureDefinitions['AllergyIntoleranceBy']], 'lastUpdated' => date('c') ], 'extension' => $this->getAllergyAnamnesisExtensions($allergy), 'clinicalStatus' => self::getCodingStructure(med_cisz_constant::$valueSet['AllergyIntoleranceClinicalStatus'], $allergy->clinicalStatusCode), 'verificationStatus' => self::getCodingStructure(med_cisz_constant::$valueSet['AllergyIntoleranceVerificationStatus'], $allergy->verificationAllergyStatusCode), 'type' => self::getCodingStructure(med_cisz_constant::$valueSet['AllergyIntoleranceType'], $allergy->typeCode), 'criticality' => $allergy->criticalityCode, 'patient' => $this->patient->link, 'encounter' => isset($this->addInfo->hospitalisation) ? null : $this->encounter->link, 'participant' => $this->practitioner->actor, 'note' => $allergy->noteAllergy ? [ (object) [ 'text' => $allergy->noteAllergy ?? null, ] ] : null, 'reaction' => [ (object) [ 'extension' => $this->getAllergyAnamnesisReactionExtension($allergy), 'manifestation' => $this->getAllergyAnamnesisReactionManifestation($allergy), 'description' => $allergy->reactionDescription, 'onset' => $allergy->reactionDate ? date('Y-m-d', strtotime($allergy->reactionDate)) : null, 'exposureRoute' => self::getCodingStructure(med_cisz_constant::$valueSet['MedicationRouteAdmin'], $allergy->roteCode), 'note' => $allergy->reactionNote ? [ (object)[ 'text' => $allergy->reactionNote ?? null, ] ] : null ] ] ] ]; if ($allergy->dateDetection && $allergy->dateLastReaction) { $allergyAnamnesis->resource->onsetPeriod = (object) [ 'start' => $allergy->dateDetection ? date('Y-m-d', strtotime($allergy->dateDetection)) : null, 'end' => $allergy->dateLastReaction ? date('Y-m-d', strtotime($allergy->dateLastReaction)) : null, ]; } elseif ($allergy->dateDetection) { $allergyAnamnesis->resource->onsetDateTime = $allergy->dateDetection ? date('Y-m-d', strtotime($allergy->dateDetection)) : null; } elseif ($allergy->dateDetectionText) { $allergyAnamnesis->resource->onsetString = $allergy->dateDetectionText ?? null; } self::cleanEntity($allergyAnamnesis); $this->allergyAnamnesis[] = $allergyAnamnesis; } } } private function getAllergyAnamnesisExtensions($allergy): ?array { $result = null; if ($allergy->substanceAllergy) { $result[] = (object)[ 'url' => med_cisz_constant::$structureDefinitions['AllergyTriggerString'], 'valueString' => $allergy->substanceAllergy ]; } if (isset($allergy->allergenAllergy->uuid)) { $result[] = (object)[ 'url' => med_cisz_constant::$structureDefinitions['MedicationAllergy'], 'valueReference' => (object)[ 'reference' => 'Medication/' . $allergy->allergenAllergy->uuid ] ]; } if ($allergy->causesAllergyCode) { $result[] = self::getValueCodeableConceptStructure( med_cisz_constant::$structureDefinitions['AllergyIntolerCategory'], med_cisz_constant::$valueSet['AllergyIntoleranceCauses'], $allergy->causesAllergyCode ); } if ($allergy->documentsByAllergy) { foreach ($allergy->documentsByAllergy as $document) { $result[] = (object)[ 'url' => med_cisz_constant::$structureDefinitions['AttachDocumentConfirmationAllergy'], 'valueReference' => (object)[ 'reference' => $document->fullUrl ] ]; } } if (isset($this->addInfo->hospitalisation)) { $result[] = (object)[ 'url' => med_cisz_constant::$structureDefinitions['HospitalisationReference'], 'valueReference' => (object)[ 'reference' => $this->addInfo->hospitalisation ] ]; } return $result; } private function getAllergyAnamnesisReactionExtension($allergy): ?array { $result = null; if ($allergy->allergenSubstanceReaction) { $result[] = (object) [ 'url' => med_cisz_constant::$structureDefinitions['ReactionSubstanceString'], 'valueString' => $allergy->allergenSubstanceReaction ]; } if ($allergy->measuresForRelief) { foreach ($allergy->measuresForReliefCodes as $code) { $codeableConcept = [ 'coding' => [ [ 'system' => med_cisz_constant::$valueSet['AEReportMeasures'], 'code' => $code ] ] ]; if ($code === 'other' && !empty($allergy->reactionNote)) { $codeableConcept['text'] = $allergy->reactionNote; } $result[] = (object) [ 'url' => med_cisz_constant::$structureDefinitions['Measures'], 'valueCodeableConcept' => $codeableConcept ]; } } if ($this->entity === 'MedStatCard') { self::loadStatMedication($allergy->allergyId); } else { self::loadMedication($allergy->allergyId); } $allergy->allergyPropose = $this->medication; if ($allergy->allergyPropose) { foreach ($allergy->allergyPropose as $propose) { if ($this->entity === 'MedStatCard') { $medication = safe_json_decode($propose->medicationJson)->medication; $result[] = (object)[ 'url' => med_cisz_constant::$structureDefinitions['MedicationsCode'], 'valueReference' => (object)[ 'reference' => 'Medication/' . $medication->uuid ] ]; } else { $this->createMedicationOrder(true); if (isset($this->medicationAllergy)) { foreach ($this->medicationAllergy as $medication) { $result[] = (object)[ 'url' => med_cisz_constant::$structureDefinitions['MedicationsCode'], 'valueReference' => (object)[ 'reference' => $medication->fullUrl ] ]; } } } } $this->medicationAllergy = null; } return $result; } private function getAllergyAnamnesisReactionManifestation($allergy): ?array { $result = []; if ($allergy->diagnosisId) { $allergyDiagnosisList = selectSqlValue($this->db, <<<SQL
                    SELECT
                        CRV.Code "code"
                    FROM CiszResourceValue CRV
                    LEFT JOIN CiszResource CR ON CRV.CiszResourceCode = CR.CiszResourceCode
                    WHERE CRV.Code = ? AND CR.Identifier = 'VSAllergyICD'
                SQL,
[$allergy->diagnosisCipher], PDO::FETCH_OBJ ); if (!$allergyDiagnosisList) { throw new Exception( med_cisz_constant::$allergyError['allergyDiagnosis']['text'], med_cisz_constant::$allergyError['allergyDiagnosis']['code'] ); } else { if (!empty($allergy->vitalSigns)) { $this->createAllergyObservations($allergy); } $firstItem = (object) [ 'concept' => self::getCodingStructure(med_cisz_constant::$valueSet['VSAllergyICD'], $allergy->diagnosisCipher) ]; if (!empty($this->observationsAllergy)) { $firstItem->reference = (object) [ 'reference' => $this->observationsAllergy[0]->fullUrl ]; } $result[] = $firstItem; if ($this->observationsAllergy) { for ($i = 1; $i < count($this->observationsAllergy); $i++) { $result[] = (object) [ 'reference' => (object) [ 'reference' => $this->observationsAllergy[$i]->fullUrl ] ]; } } return $result; } } elseif (!empty($allergy->vitalSigns)) { $this->createAllergyObservations($allergy); foreach ($this->observationsAllergy as $observation) { $result[] = (object) [ 'reference' => (object) [ 'reference' => $observation->fullUrl, ] ]; } return $result; } else { foreach ($this->observationsAllergy as $observation) { if ($observation->resource->code->coding[0]->code === 'skin') $result[] = (object) [ 'reference' => (object) [ 'reference' => $observation->fullUrl, ] ]; } } return $result; } private function getVitalSignsForReactions(array $reactionIds): array { if (empty($reactionIds)) { return []; } $placeholders = implode(',', array_fill(0, count($reactionIds), '?')); $sqlVitalSigns = <<<SQL
        SELECT
            MARVS.MedAllergyReactionCode    "reactionId",
            MARVS.Type                      "type",
            MARVS.ValueNumber               "valueNumber"
        FROM MedAllergyReactionVitalSigns AS MARVS
        WHERE MARVS.MedAllergyReactionCode IN ({$placeholders})
        ORDER BY MARVS.MedAllergyReactionCode, MARVS.Type
    SQL;
$stmt = $this->db->prepare($sqlVitalSigns); $stmt->execute($reactionIds); $vitalSigns = $stmt->fetchAll(PDO::FETCH_OBJ); $vitalSignsByReaction = []; foreach ($vitalSigns as $sign) { $reactionId = $sign->reactionId; if (!isset($vitalSignsByReaction[$reactionId])) { $vitalSignsByReaction[$reactionId] = []; } $vitalSignsByReaction[$reactionId][] = $sign; } return $vitalSignsByReaction; } } 